import{_ as e,o as a,c as d,a6 as r}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"SKU系列与导出检查","description":"","frontmatter":{"id":"sku","title":"SKU系列与导出检查","chapter":"03","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["footwear-skills"],"order":24,"content_kind":"操作教程"},"headers":[],"relativePath":"ecommerce/sku.md","filePath":"ecommerce/sku.md"}'),s={name:"ecommerce/sku.md"};function o(n,t,i,l,h,c){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="sku系列与导出-复制母版时检查差异" tabindex="-1">SKU系列与导出，复制母版时检查差异 <a class="header-anchor" href="#sku系列与导出-复制母版时检查差异" aria-label="Permalink to &quot;SKU系列与导出，复制母版时检查差异&quot;">​</a></h1><p>这节以榨汁杯奶油白与薄荷绿练习说明怎样复用套图。两个颜色都需要真实实拍，不从原稿名称推断实际存在。完成后应有SKU差异表、各SKU源文件、逐张图片与交付清单。</p><h2 id="_1-先列差异-不急着批量出图" tabindex="-1">1. 先列差异，不急着批量出图 <a class="header-anchor" href="#_1-先列差异-不急着批量出图" aria-label="Permalink to &quot;1. 先列差异，不急着批量出图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>白色款</th><th>绿色款</th><th>能否共用</th></tr></thead><tbody><tr><td>真实商品照片</td><td>white-front</td><td>green-front</td><td>必须分别使用</td></tr><tr><td>尺寸/容量/功率</td><td>按真实资料</td><td>按真实资料</td><td>相同且有依据才共用</td></tr><tr><td>发货配件</td><td>实际清单</td><td>实际清单</td><td>核对后决定</td></tr><tr><td>背景与字体</td><td>已通过母版</td><td>复用风格</td><td>可以复用</td></tr><tr><td>颜色文案</td><td>奶油白</td><td>薄荷绿</td><td>分别替换</td></tr></tbody></table><h2 id="_2-复制源文件并换真实主体" tabindex="-1">2. 复制源文件并换真实主体 <a class="header-anchor" href="#_2-复制源文件并换真实主体" aria-label="Permalink to &quot;2. 复制源文件并换真实主体&quot;">​</a></h2><p>从已完成的白色套图PSD另存绿色版，逐个替换商品层及相关局部照片。背景、标题位置和文字样式可保留，颜色名、数值和配件说明逐项更新。第一张换好后放大检查边缘与光线，缩成手机宽度看识别，再做其他五张。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请根据两个SKU的真实事实表与素材索引，生成套图差异清单。逐项比较外观、颜色、规格、配件、使用步骤和准确文案，给出每张图要替换的商品照片、文字层和参数。</span></span>
<span class="line"><span>可共用背景与版式，但不得通过改色代替真实SKU照片。未确认相同的字段不要直接沿用。输出修改清单与文件命名，不生成图片，不把计划记成已经完成。</span></span></code></pre></div><h2 id="_3-整套并排看-再导出" tabindex="-1">3. 整套并排看，再导出 <a class="header-anchor" href="#_3-整套并排看-再导出" aria-label="Permalink to &quot;3. 整套并排看，再导出&quot;">​</a></h2><p>把两套预览按同一顺序并排。商品比例、标题位置、背景光线应协调，产品颜色仍以各自实拍为准。尺寸不同的SKU不能沿用相同尺寸图。文件名包含SKU、颜色、用途、语言和版本，重新打开每张图片后核清单。</p><p>完整多渠道交付表见<a href="./cross-border-sku-delivery">跨境SKU教程</a>，六张图具体操作见<a href="./image-set">套图教程</a>。本项目尚未以真实两款商品生成或排版。</p>`,10)])])}const u=e(s,[["render",o]]);export{_ as __pageData,u as default};
